package dev.capcap.mobile;
import java.util.*;
import java.util.regex.*;
final class Srt {
 static final Pattern TIME=Pattern.compile("(\\d{2,}):(\\d{2}):(\\d{2})[,.](\\d{3})");
 static final class Cue {final long start,end;final String text;Cue(long s,long e,String t){start=s;end=e;text=t;}}
 static long millis(String s){Matcher m=TIME.matcher(s.trim());if(!m.matches())throw new IllegalArgumentException("Mốc thời gian SRT không hợp lệ");long h=Long.parseLong(m.group(1)),min=Long.parseLong(m.group(2)),sec=Long.parseLong(m.group(3));if(min>59||sec>59||h>9999)throw new IllegalArgumentException("Mốc thời gian ngoài phạm vi");return ((h*60+min)*60+sec)*1000+Long.parseLong(m.group(4));}
 static List<Cue> parse(String input){List<Cue> out=new ArrayList<>();String normalized=input.replace("\uFEFF","").replace("\r\n","\n").replace('\r','\n').trim();if(normalized.isEmpty())return out;if(normalized.startsWith("[Script Info]")||normalized.startsWith("[Events]"))return parseAss(normalized);if(normalized.equals("WEBVTT")||normalized.startsWith("WEBVTT\n")||normalized.startsWith("WEBVTT "))return parseVtt(normalized);for(String block:normalized.split("\\n(?:[ \\t]*\\n)+")){String[] lines=block.split("\\n");int i=lines[0].trim().matches("\\d+")?1:0;if(lines.length<=i+1)throw new IllegalArgumentException("Thiếu nội dung phụ đề");String[] times=lines[i].split("-->",-1);if(times.length!=2)throw new IllegalArgumentException("Thiếu mốc thời gian");long s=millis(times[0]),e=millis(times[1]);if(e<=s)throw new IllegalArgumentException("Thời gian kết thúc phải sau bắt đầu");StringBuilder text=new StringBuilder();for(int j=i+1;j<lines.length;j++){if(j>i+1)text.append('\n');text.append(lines[j]);}out.add(new Cue(s,e,text.toString()));}Collections.sort(out,(a,b)->Long.compare(a.start,b.start));return out;}
 static List<Cue> parseVtt(String input){List<Cue> out=new ArrayList<>();String[] blocks=input.split("\\n(?:[ \\t]*\\n)+");for(int k=1;k<blocks.length;k++){String block=blocks[k];if(block.equals("NOTE")||block.startsWith("NOTE ")||block.startsWith("NOTE\n")||block.startsWith("STYLE\n")||block.startsWith("REGION\n"))continue;String[] lines=block.split("\\n");int i=lines[0].contains("-->")?0:1;if(lines.length<=i+1)throw new IllegalArgumentException("WebVTT thiếu nội dung");String[] times=lines[i].split("-->",-1);if(times.length!=2)throw new IllegalArgumentException("WebVTT thiếu mốc thời gian");long s=vttMillis(times[0].trim()),e=vttMillis(times[1].trim().split("\\s+",2)[0]);if(e<=s)throw new IllegalArgumentException("WebVTT thời gian không hợp lệ");StringBuilder body=new StringBuilder();for(int j=i+1;j<lines.length;j++){if(j>i+1)body.append('\n');body.append(lines[j]);}out.add(new Cue(s,e,body.toString()));}Collections.sort(out,(a,b)->Long.compare(a.start,b.start));return out;}
 static List<Cue> parseAss(String input){List<Cue> out=new ArrayList<>();boolean events=false;String[] fields=null;for(String raw:input.split("\\n")){String line=raw.trim();if(line.startsWith("[")){events=line.equalsIgnoreCase("[Events]");continue;}if(!events)continue;if(line.startsWith("Format:")){fields=line.substring(7).trim().split("\\s*,\\s*");continue;}if(!line.startsWith("Dialogue:"))continue;if(fields==null)throw new IllegalArgumentException("ASS thiếu Format");String[] values=line.substring(9).trim().split(",",fields.length);int a=-1,b=-1,t=-1;for(int i=0;i<fields.length;i++){if(fields[i].equalsIgnoreCase("Start"))a=i;if(fields[i].equalsIgnoreCase("End"))b=i;if(fields[i].equalsIgnoreCase("Text"))t=i;}if(a<0||b<0||t!=fields.length-1||values.length!=fields.length)throw new IllegalArgumentException("ASS Format không hỗ trợ");long s=assMillis(values[a]),e=assMillis(values[b]);if(e<=s)throw new IllegalArgumentException("ASS thời gian không hợp lệ");String body=values[t].replaceAll("\\{[^}]*\\}","").replace("\\N","\n").replace("\\n","\n").replace("\\h"," ");out.add(new Cue(s,e,body));}Collections.sort(out,(a,b)->Long.compare(a.start,b.start));return out;}
 static long assMillis(String value){String s=value.trim();if(!s.matches("\\d{1,4}:\\d{2}:\\d{2}\\.\\d{2}"))throw new IllegalArgumentException("ASS timestamp không hợp lệ");return millis((s.indexOf(':')==1?"0":"")+s+"0");}
 static long vttMillis(String s){return millis(s.indexOf(':')==s.lastIndexOf(':')?"00:"+s:s);}
 static String format(long ms){return String.format(java.util.Locale.ROOT,"%02d:%02d:%02d,%03d",ms/3600000,(ms/60000)%60,(ms/1000)%60,ms%1000);}
 static String at(List<Cue> cues,long ms){StringBuilder b=new StringBuilder();for(Cue c:cues){if(c.start>ms)break;if(ms<c.end){if(b.length()>0)b.append('\n');b.append(c.text);}}return b.toString();}
}
